<?php

declare(strict_types=1);

namespace Hypervel\Passport\Database\Factories;

use Hypervel\Database\Eloquent\Factories\Factory;
use Hypervel\Passport\KeyGenerator;
use Hypervel\Passport\Passport;
use Hypervel\Passport\SigningKey;
use Hypervel\Support\Facades\Date;

/**
 * @extends Factory<SigningKey>
 */
class SigningKeyFactory extends Factory
{
    /**
     * @var null|array{private: string, public: string}
     */
    protected static ?array $keys = null;

    /**
     * Get the name of the model that is generated by the factory.
     *
     * @return class-string<SigningKey>
     */
    public function modelName(): string
    {
        return $this->model ?? Passport::signingKeyModel();
    }

    /**
     * Define the model's default state.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        // This immutable test pair can be reused without blocking on generation per test.
        $keys = static::$keys ??= (new KeyGenerator)->generate(2048);

        return [
            'public_key' => $keys['public'],
            'private_key' => $keys['private'],
            'activates_at' => Date::now(),
            'max_token_lifetime' => 0,
            'retain_until' => null,
            'retires_at' => null,
        ];
    }

    /**
     * Flush all static state.
     */
    public static function flushState(): void
    {
        static::$keys = null;
    }
}
